INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Fix and Flip Series : Time Hacks', 'Smart Money South Florida', 'Real Estate Meetings', 'MONDAY 5 PM PST 7 PM CST 8 PM EST [SIGN UP HERE](https://link.elitereimm.com/widget/form/wSbrsstjtpMx77vSSif7?am_id=debbie5574) Use CRM,', 'MONDAY 5 PM PST 7 PM CST 8 PM EST [SIGN UP HERE](https://link.elitereimm.com/widget/form/wSbrsstjtpMx77vSSif7?am_id=debbie5574) Use CRM, systems, automation, and AI to run flips more efficiently without letting every project take over your life. Fixing and flipping can become a full-time job fast. Contractors need answers. Materials need to be ordered. Draws need to be tracked. Budgets change. Inspections get scheduled. Properties need to be marketed. And somehow you are still supposed to find More info: https://www.meetup.com/south-florida-multifamily-and-more-investor-club/events/316784645/', '2026-10-12T20:00:00-04:00', 'Online event', 'Online event', 'Fort Lauderdale', 'FL', '', 26.12, -80.14, 'Smart Money South Florida', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/south-florida-multifamily-and-more-investor-club/events/316784645/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('[Virtual] Simple Real Estate Strategies That Work (Fun, Free, & Gets You Paid!)', 'Smart Money South Florida', 'Real Estate Meetings', '**Most real estate trainings are like bad lectures:** boring, overloaded with information, and leaving you feeling like you’ll need weeks', '**Most real estate trainings are like bad lectures:** boring, overloaded with information, and leaving you feeling like you’ll need weeks of prep just to get started (or worst of all, they just want to sell you their expensive course or coaching). **We decided to do the exact opposite**—and hundreds of agents now agree. Join us **LIVE (virtual) every Wednesday at 9:00 AM CST** for a zero-fluff, action-packed call where active, top-producing agents openly share exactly what’s working right More info: https://www.meetup.com/south-florida-multifamily-and-more-investor-club/events/316694104/', '2026-10-14T10:00:00-04:00', 'Online event', 'Online event', 'Fort Lauderdale', 'FL', '', 26.12, -80.14, 'Smart Money South Florida', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/south-florida-multifamily-and-more-investor-club/events/316694104/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('RE-AI Advantage Lab: Turn AI Into Your Real Estate Advantage', 'Smart Money South Florida', 'Real Estate Meetings', 'AI is changing what “work” looks like for real estate agents. Tasks that used to take hours can now take minutes. Marketing can be created', 'AI is changing what “work” looks like for real estate agents. Tasks that used to take hours can now take minutes. Marketing can be created faster. Follow up can be smarter. Content can be generated almost instantly. But most agents are still trying to figure out **how to actually use AI in their day-to-day business.** That is exactly what we will be exploring inside the **RE-AI Advantage Lab.** This weekly training is designed specifically for real estate agents who want to learn how to use AI More info: https://www.meetup.com/south-florida-multifamily-and-more-investor-club/events/316695004/', '2026-10-14T11:00:00-04:00', 'Online event', 'Online event', 'Fort Lauderdale', 'FL', '', 26.12, -80.14, 'Smart Money South Florida', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/south-florida-multifamily-and-more-investor-club/events/316695004/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Real Estate Virtual Coffee Mastermind', 'Smart Money South Florida', 'Real Estate Meetings', '**Start your morning...** with a coffee & friends from all over the country. Don''t miss out on our live (virtual) networking event every', '**Start your morning...** with a coffee & friends from all over the country. Don''t miss out on our live (virtual) networking event every Thursday morning. It''s the perfect opportunity to build relationships with Realtors across the state and across the country (sometimes even on the other side of the world) that will serve your clients well when they need a referral. We have a short educational/informative presentation at the beginning of the meeting and then go into 3 or 4 person breakout More info: https://www.meetup.com/south-florida-multifamily-and-more-investor-club/events/316709243/', '2026-10-15T10:00:00-04:00', 'Online event', 'Online event', 'Fort Lauderdale', 'FL', '', 26.12, -80.14, 'Smart Money South Florida', 1, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/south-florida-multifamily-and-more-investor-club/events/316709243/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
